def booleanMatrix(matrix):
	fRow = 0
	(row, col) = (len(matrix), len(matrix[0]))
	for i in range(col):
		if matrix[0][i] == 1:
			fRow = 1
			break
	for r in range(row):
		for c in range(col):
			if matrix[r][c] == 1:
				matrix[r][0] = matrix[0][c] = 1
	for r in range(1, row):
		for c in range(1, col):
			if matrix[r][0] == 1 or matrix[0][c] == 1:
				matrix[r][c] = 1
	if matrix[0][0] == 1:
		for r in range(row):
			matrix[r][0] = 1
	if fRow:
		for c in range(col):
			matrix[0][c] = 1
